using Microsoft.EntityFrameworkCore;

// Cosmos DB context demonstrating EF Core 9 breaking-change fixes.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "CatalogDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: the Cosmos provider now uses "$type" as the
        // default discriminator property. Existing documents already store the value
        // under "Discriminator". Explicitly configure the old property name so EF
        // can read existing documents without a data migration.
        modelBuilder.Entity<Product>()
            .HasDiscriminant<string>("Discriminator")
            .HasValue<Product>(nameof(Product));
    }

    // EF Core 9 breaking change: synchronous Cosmos DB queries are no longer
    // supported and throw InvalidOperationException at runtime. All queries
    // must use the async API (ToListAsync, FirstOrDefaultAsync, etc.).
    //
    // BEFORE (broken in EF Core 9):
    //   var items = db.Products.Where(p => p.Price > 10).ToList();
    //
    // AFTER (required fix):
    //   var items = await db.Products.Where(p => p.Price > 10).ToListAsync();
    public async Task<List<Product>> GetExpensiveProductsAsync(decimal minPrice)
        => await Products.Where(p => p.Price > minPrice).ToListAsync();
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public decimal Price { get; set; }
}

